1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。任意规则节点可附布尔 nullable：
17	//   true 在原接受集合上加入 null（必填字段仍不得缺失，空正文不等于 null）。
18	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
19	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
20	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
21	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
22	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
23	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
24	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
25	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
26	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
27	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
28	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
29	//   报告写 stdout，不监听、不发送请求、不修改文件。
30	// - replay 子命令：本机请求重放与响应差异报告。读取同一份请求记录快照，
31	//   按输入顺序把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口
32	//   （每条只尝试一次、不跟随重定向、每条有覆盖完整收发的总超时），
33	//   仅比较实际响应的状态码与正文原始字节和记录中的计划响应；
34	//   报告写 stdout，不监听、不修改文件。
35	
36	import http from 'node:http';
37	import { readFile } from 'node:fs/promises';
38	import path from 'node:path';
39	
40	const APP_NAME = 'contractlab';
41	
42	// 管理入口（保留前缀，业务接口不得使用）
43	const ADMIN_PREFIX = '/__contractlab/';
44	const ADMIN_BASE = '/__contractlab';
45	const HEALTH_PATH = '/__contractlab/health';
46	const RELOAD_PATH = '/__contractlab/reload';
47	const REQUESTS_PATH = '/__contractlab/requests';
48	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
49	
50	// 每个业务响应都携带当前配置版本
51	const VERSION_HEADER = 'X-Contractlab-Version';
52	
53	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
54	const MAX_BODY_BYTES = 100 * 1024 * 1024;
55	
56	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
57	const BLOCKED_HEADERS = new Set([
58	  'connection',
59	  'keep-alive',
60	  'content-length',
61	  'transfer-encoding',
62	]);
63	
64	// RFC 7230 token：合法的 HTTP 头名称字符
65	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
66	
67	type HttpMethod = 'GET' | 'POST';
68	
69	// ---------------------------------------------------------------------------
70	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
71	// ---------------------------------------------------------------------------
72	//
73	// 规则格式（JSON 对象，未知字段一律拒绝）：
74	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
75	//   { "type": "array", "items": <规则> }
76	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
77	// 任意规则节点（根、字段、数组元素）可附布尔 "nullable"：省略或 false 行为不变，
78	// true 在原接受集合上加入 null（type:null 本就只接受 null）。必填字段即使可空也
79	// 不能缺失；null 被接受时不产生子节点差异，非 null 值仍须通过全部原约束。
80	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
81	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
82	// array 必须声明 items。
83	
84	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
85	
86	type BodyRule =
87	  | {
88	      readonly kind: 'object';
89	      readonly fields: ReadonlyMap<string, FieldRule>;
90	      readonly additionalProperties: boolean;
91	      readonly nullable: boolean;
92	    }
93	  | { readonly kind: 'array'; readonly items: BodyRule; readonly nullable: boolean }
94	  | { readonly kind: ScalarKind; readonly nullable: boolean };
95	
96	interface FieldRule {
97	  readonly rule: BodyRule;
98	  readonly required: boolean;
99	}
100	
101	interface ResponseSpec {
102	  readonly status: number;
103	  readonly headers: { readonly [name: string]: string };
104	  readonly body: string;
105	  readonly delay: number;
106	}
107	
108	interface EndpointSpec {
109	  readonly method: HttpMethod;
110	  readonly path: string;
111	  readonly responses: readonly ResponseSpec[];
112	  readonly bodyRule: BodyRule | undefined;
113	}
114	
115	interface LiveEndpoint {
116	  readonly key: string;
117	  readonly responses: readonly ResponseSpec[];
118	  readonly bodyRule: BodyRule | undefined;
119	  // 下一个待预留位置；到达末项后停在末项（持续复用）
120	  cursor: number;
121	}
122	
123	interface LiveState {
124	  readonly version: number;
125	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
126	}
127	
128	interface ReloadResult {
129	  ok: boolean;
130	  version: number;
131	  error?: string;
132	}
133	
134	class ConfigError extends Error {
135	  constructor(message: string) {
136	    super(message);
137	    this.name = 'ConfigError';
138	  }
139	}
140	
141	// ---------------------------------------------------------------------------
142	// 配置校验
143	// ---------------------------------------------------------------------------
144	
145	function isPlainObject(value: unknown): value is Record<string, unknown> {
146	  return typeof value === 'object' && value !== null && !Array.isArray(value);
147	}
148	
149	function validatePath(p: string, where: string): void {
150	  if (p.length === 0 || p[0] !== '/') {
151	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
152	  }
153	  if (p.length > 4096) {
154	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
155	  }
156	  for (const ch of p) {
157	    const code = ch.charCodeAt(0);
158	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
159	      throw new ConfigError(
160	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
161	      );
162	    }
163	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
164	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
165	    }
166	  }
167	}
168	
169	function validateResponse(raw: unknown, where: string): ResponseSpec {
170	  if (!isPlainObject(raw)) {
171	    throw new ConfigError(`${where} 必须是对象`);
172	  }
173	  for (const key of Object.keys(raw)) {
174	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
175	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
176	    }
177	  }
178	
179	  const { status, headers, body, delay } = raw;
180	
181	  if (!Number.isInteger(status) || status < 200 || status > 599) {
182	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
183	  }
184	
185	  if (!isPlainObject(headers)) {
186	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
187	  }
188	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
189	  const cleanHeaders: { [name: string]: string } = Object.create(null);
190	  const seenNames = new Set<string>();
191	  for (const [name, value] of Object.entries(headers)) {
192	    const whereHeader = `${where}.headers["${name}"]`;
193	    if (!HEADER_NAME_RE.test(name)) {
194	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
195	    }
196	    const lower = name.toLowerCase();
197	    if (BLOCKED_HEADERS.has(lower)) {
198	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
199	    }
200	    if (seenNames.has(lower)) {
201	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
202	    }
203	    if (typeof value !== 'string') {
204	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
205	    }
206	    for (let i = 0; i < value.length; i += 1) {
207	      const code = value.charCodeAt(i);
208	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
209	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
210	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
211	        throw new ConfigError(
212	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
213	        );
214	      }
215	    }
216	    seenNames.add(lower);
217	    cleanHeaders[name] = value;
218	  }
219	
220	  if (typeof body !== 'string') {
221	    throw new ConfigError(`${where}.body 必须是文本字符串`);
222	  }
223	  if ((status === 204 || status === 304) && body !== '') {
224	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
225	  }
226	
227	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
228	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
229	  }
230	
231	  return { status, headers: cleanHeaders, body, delay };
232	}
233	
234	const SCALAR_KINDS: ReadonlySet<string> = new Set([
235	  'string',
236	  'number',
237	  'integer',
238	  'boolean',
239	  'null',
240	]);
241	
242	function validateBodyRule(raw: unknown, where: string): BodyRule {
243	  if (!isPlainObject(raw)) {
244	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
245	  }
246	
247	  const type = raw.type;
248	  const allowed = new Set(['type', 'nullable']);
249	  if (type === 'object') {
250	    allowed.add('fields');
251	    allowed.add('additionalProperties');
252	  } else if (type === 'array') {
253	    allowed.add('items');
254	  } else if (!SCALAR_KINDS.has(type as string)) {
255	    throw new ConfigError(
256	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
257	    );
258	  }
259	  for (const key of Object.keys(raw)) {
260	    if (!allowed.has(key)) {
261	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
262	    }
263	  }
264	
265	  // 任意规则节点可附布尔 nullable：省略或 false 不变，true 在原接受集合上加入 null
266	  const nullableRaw = raw.nullable;
267	  if (nullableRaw !== undefined && typeof nullableRaw !== 'boolean') {
268	    throw new ConfigError(`${where}.nullable 必须是布尔值，收到 ${JSON.stringify(nullableRaw)}`);
269	  }
270	  const nullable = nullableRaw === true;
271	
272	  if (type === 'object') {
273	    const fieldsRaw = raw.fields;
274	    const fields = new Map<string, FieldRule>();
275	    if (fieldsRaw !== undefined) {
276	      if (!isPlainObject(fieldsRaw)) {
277	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
278	      }
279	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
280	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
281	      }
282	    }
283	    const additional = raw.additionalProperties;
284	    if (additional !== undefined && typeof additional !== 'boolean') {
285	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
286	    }
287	    // 未声明字段默认拒绝
288	    return { kind: 'object', fields, additionalProperties: additional === true, nullable };
289	  }
290	
291	  if (type === 'array') {
292	    if (raw.items === undefined) {
293	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
294	    }
295	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`), nullable };
296	  }
297	
298	  return { kind: type as ScalarKind, nullable };
299	}
300	
301	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
302	function validateFieldRule(raw: unknown, where: string): FieldRule {
303	  if (!isPlainObject(raw)) {
304	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
305	  }
306	  let required = false;
307	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
308	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
309	  const rest: Record<string, unknown> = Object.create(null);
310	  for (const [key, value] of Object.entries(raw)) {
311	    if (key === 'required') {
312	      if (typeof value !== 'boolean') {
313	        throw new ConfigError(`${where}.required 必须是布尔值`);
314	      }
315	      required = value;
316	    } else {
317	      rest[key] = value;
318	    }
319	  }
320	  return { rule: validateBodyRule(rest, where), required };
321	}
322	
323	function validateEndpoint(
324	  raw: unknown,
325	  index: number,
326	  seen: Set<string>,
327	): EndpointSpec {
328	  const where = `endpoints[${index}]`;
329	  if (!isPlainObject(raw)) {
330	    throw new ConfigError(`${where} 必须是对象`);
331	  }
332	  for (const key of Object.keys(raw)) {
333	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
334	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
335	    }
336	  }
337	
338	  const { method, path: routePath, responses, requestBody } = raw;
339	
340	  if (method !== 'GET' && method !== 'POST') {
341	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
342	  }
343	
344	  if (typeof routePath !== 'string') {
345	    throw new ConfigError(`${where}.path 必须是字符串`);
346	  }
347	  validatePath(routePath, where);
348	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
349	    throw new ConfigError(
350	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
351	    );
352	  }
353	
354	  const key = `${method} ${routePath}`;
355	  if (seen.has(key)) {
356	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
357	  }
358	  seen.add(key);
359	
360	  if (!Array.isArray(responses) || responses.length === 0) {
361	    throw new ConfigError(`${where}.responses 必须是非空数组`);
362	  }
363	  const cleanResponses = responses.map((item, j) =>
364	    validateResponse(item, `${where}.responses[${j}]`),
365	  );
366	
367	  let bodyRule: BodyRule | undefined;
368	  if (requestBody !== undefined) {
369	    if (method !== 'POST') {
370	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
371	    }
372	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
373	  }
374	
375	  return { method, path: routePath, responses: cleanResponses, bodyRule };
376	}
377	
378	function validateConfig(raw: unknown): EndpointSpec[] {
379	  if (!isPlainObject(raw)) {
380	    throw new ConfigError('配置顶层必须是 JSON 对象');
381	  }
382	  for (const key of Object.keys(raw)) {
383	    if (key !== 'endpoints') {
384	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
385	    }
386	  }
387	  const list = raw.endpoints;
388	  if (!Array.isArray(list) || list.length === 0) {
389	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
390	  }
391	  const seen = new Set<string>();
392	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
393	}
394	
395	// ---------------------------------------------------------------------------
396	// 运行时状态：配置快照 + 每接口独立序列
397	// ---------------------------------------------------------------------------
398	
399	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
400	  const endpoints = new Map<string, LiveEndpoint>();
401	  for (const spec of specs) {
402	    endpoints.set(`${spec.method} ${spec.path}`, {
403	      key: `${spec.method} ${spec.path}`,
404	      responses: spec.responses,
405	      bodyRule: spec.bodyRule,
406	      cursor: 0,
407	    });
408	  }
409	  return { version, endpoints };
410	}
411	
412	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
413	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
414	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
415	function reserveNext(endpoint: LiveEndpoint): { position: number; item: ResponseSpec } {
416	  const last = endpoint.responses.length - 1;
417	  const position = endpoint.cursor < last ? endpoint.cursor : last;
418	  if (endpoint.cursor < last) {
419	    endpoint.cursor += 1;
420	  }
421	  return { position, item: endpoint.responses[position] };
422	}
423	
424	// ---------------------------------------------------------------------------
425	// 进程内请求记录
426	// ---------------------------------------------------------------------------
427	//
428	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
429	// 未收完整即断开或超出上限不创建记录、不消费序列。
430	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
431	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
432	
433	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
434	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
435	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
436	//   interrupted —— 写出完成前连接断开或写入/发送失败
437	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
438	
439	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
440	interface PlannedResponseSnapshot {
441	  readonly kind: 'scene' | 'framework';
442	  readonly status: number;
443	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
444	  readonly headers: { readonly [name: string]: string };
445	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
446	  readonly body: string;
447	}
448	
449	interface RequestRecord {
450	  readonly id: number;
451	  readonly receivedAt: string;
452	  readonly request: {
453	    readonly method: string;
454	    // 含查询串的原始请求目标
455	    readonly target: string;
456	    readonly path: string;
457	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
458	    readonly rawHeaders: readonly string[];
459	    readonly bodyBytes: number;
460	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
461	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
462	  };
463	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
464	  configVersion: number;
465	  // matched=false：未匹配（404），不消费任何序列
466	  matched: boolean;
467	  endpoint: string | null;
468	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
469	  bodyValidationPassed: boolean | null;
470	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
471	  bodyRejection: BodyReport | null;
472	  // 场景请求在序列中的消费位置（0 起）；400/404 没有消费位置，记为 null
473	  sequencePosition: number | null;
474	  sequenceLength: number | null;
475	  plannedResponse: PlannedResponseSnapshot | null;
476	  delivery: DeliveryStatus;
477	}
478	
479	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
480	class RequestLog {
481	  private records: RequestRecord[] = [];
482	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
483	  private readonly live = new Map<number, RequestRecord>();
484	  private nextId = 1;
485	
486	  create(entry: {
487	    method: string;
488	    target: string;
489	    path: string;
490	    rawHeaders: readonly string[];
491	    body: Buffer;
492	    configVersion: number;
493	  }): RequestRecord {
494	    const id = this.nextId;
495	    this.nextId += 1;
496	    const record: RequestRecord = {
497	      id,
498	      receivedAt: new Date().toISOString(),
499	      request: {
500	        method: entry.method,
501	        target: entry.target,
502	        path: entry.path,
503	        rawHeaders: entry.rawHeaders,
504	        bodyBytes: entry.body.byteLength,
505	        body: encodeBodyLosslessly(entry.body),
506	      },
507	      configVersion: entry.configVersion,
508	      matched: false,
509	      endpoint: null,
510	      bodyValidationPassed: null,
511	      bodyRejection: null,
512	      sequencePosition: null,
513	      sequenceLength: null,
514	      plannedResponse: null,
515	      delivery: 'pending',
516	    };
517	    this.records.push(record);
518	    this.live.set(id, record);
519	    return record;
520	  }
521	
522	  // 写出完成；对已清空（不再存活）的记录是 no-op
523	  markDelivered(id: number, status: DeliveryStatus): void {
524	    const record = this.live.get(id);
525	    if (!record) {
526	      return;
527	    }
528	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
529	    if (record.delivery === 'sent') {
530	      return;
531	    }
532	    record.delivery = status;
533	  }
534	
535	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
536	  snapshot(): readonly RequestRecord[] {
537	    return [...this.records];
538	  }
539	
540	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
541	  // 清空前已完整接收的请求随后完成或失败都不再出现。
542	  clear(): number {
543	    const removed = this.records.length;
544	    this.records = [];
545	    this.live.clear();
546	    return removed;
547	  }
548	}
549	
550	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
551	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
552	// ignoreBOM：开头 BOM（EF BB BF）必须保留在文本中（默认行为会将其丢弃），
553	// 否则文本重新编码回不去原始字节，快照就不再无损。
554	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
555	  try {
556	    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body);
557	    return { encoding: 'utf-8', content: text };
558	  } catch {
559	    return { encoding: 'base64', content: body.toString('base64') };
560	  }
561	}
