563	// ---------------------------------------------------------------------------
564	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
565	// ---------------------------------------------------------------------------
566	
567	interface StructureProblem {
568	  readonly pointer: string;
569	  readonly expected: string;
570	  readonly actual: string;
571	}
572	
573	interface BodyReport {
574	  readonly error: 'invalid_request_body';
575	  readonly stage: 'parse' | 'structure';
576	  readonly message: string;
577	  readonly problems: readonly StructureProblem[];
578	}
579	
580	function parseFailure(message: string): BodyReport {
581	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
582	}
583	
584	function jsonTypeOf(value: unknown): string {
585	  if (value === null) {
586	    return 'null';
587	  }
588	  if (Array.isArray(value)) {
589	    return 'array';
590	  }
591	  return typeof value;
592	}
593	
594	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
595	function escapePointerSegment(segment: string): string {
596	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
597	}
598	
599	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
600	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
601	// 可空规则：null 被直接接受，不产生任何子节点差异；非 null 继续检查全部原约束。
602	function checkRule(
603	  rule: BodyRule,
604	  value: unknown,
605	  pointer: string,
606	  problems: StructureProblem[],
607	): void {
608	  if (value === null && rule.nullable) {
609	    return;
610	  }
611	  switch (rule.kind) {
612	    case 'string':
613	    case 'boolean':
614	      if (typeof value !== rule.kind) {
615	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
616	      }
617	      return;
618	    case 'null':
619	      if (value !== null) {
620	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
621	      }
622	      return;
623	    case 'number':
624	      if (typeof value !== 'number' || !Number.isFinite(value)) {
625	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
626	      }
627	      return;
628	    case 'integer':
629	      if (!Number.isInteger(value)) {
630	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
631	      }
632	      return;
633	    case 'array': {
634	      if (!Array.isArray(value)) {
635	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
636	        return;
637	      }
638	      for (let i = 0; i < value.length; i += 1) {
639	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
640	      }
641	      return;
642	    }
643	    case 'object': {
644	      if (!isPlainObject(value)) {
645	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
646	        return;
647	      }
648	      for (const [name, field] of rule.fields) {
649	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
650	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
651	          if (field.required) {
652	            problems.push({
653	              pointer: childPointer,
654	              expected: `${field.rule.kind}（必填字段）`,
655	              actual: 'missing',
656	            });
657	          }
658	        } else {
659	          checkRule(field.rule, value[name], childPointer, problems);
660	        }
661	      }
662	      if (!rule.additionalProperties) {
663	        for (const key of Object.keys(value)) {
664	          if (!rule.fields.has(key)) {
665	            problems.push({
666	              pointer: `${pointer}/${escapePointerSegment(key)}`,
667	              expected: '未声明的字段（不允许）',
668	              actual: jsonTypeOf(value[key]),
669	            });
670	          }
671	        }
672	      }
673	      return;
674	    }
675	  }
676	}
677	
678	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
679	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
680	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
681	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
682	// 在线与离线对同一组字节给出同一结论。
683	function validateBodyWithContentType(
684	  contentType: string | undefined,
685	  body: Buffer,
686	  rule: BodyRule,
687	): BodyReport | null {
688	  const mediaType =
689	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
690	  if (mediaType !== 'application/json') {
691	    return parseFailure(
692	      typeof contentType === 'string'
693	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
694	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
695	    );
696	  }
697	
698	  if (body.length === 0) {
699	    return parseFailure('请求正文为空，无法解析为 JSON');
700	  }
701	
702	  let text: string;
703	  try {
704	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
705	  } catch {
706	    return parseFailure('请求正文不是合法的 UTF-8 编码');
707	  }
708	
709	  let parsed: unknown;
710	  try {
711	    parsed = JSON.parse(text);
712	  } catch (e) {
713	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
714	  }
715	
716	  const problems: StructureProblem[] = [];
717	  checkRule(rule, parsed, '', problems);
718	  if (problems.length > 0) {
719	    return {
720	      error: 'invalid_request_body',
721	      stage: 'structure',
722	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
723	      problems,
724	    };
725	  }
726	  return null;
727	}
