998	  if (oldRule.additionalProperties) {
999	    if (!newRule.additionalProperties) {
1000	      const name = freshFieldName(oldRule.fields, newRule.fields);
1001	      out.push({
1002	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1003	        value: sampleObjectWith(oldRule, name, 0),
1004	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
1005	      });
1006	    } else {
