1035	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
1036	  const base = { method: oldEp.method, path: oldEp.path };
1037	
1038	  if (!newEp) {
1039	    return {
1040	      ...base,
1041	      compatible: false,
1042	      reasons: [
1043	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
1044	      ],
1045	      example: acceptedRequestExample(oldEp),
1046	    };
1047	  }
1048	
1049	  if (!oldEp.bodyRule && !newEp.bodyRule) {
1050	    return { ...base, compatible: true, reasons: [] };
1051	  }
1052	
1053	  if (!oldEp.bodyRule && newEp.bodyRule) {
1054	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1055	    return {
1056	      ...base,
1057	      compatible: false,
1058	      reasons: [
1059	        {
1060	          pointer: '',
1061	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1062	        },
1063	      ],
1064	      example: {
1065	        ...base,
1066	        headers: { 'Content-Type': 'application/json' },
1067	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1068	      },
1069	    };
1070	  }
1071	
1072	  if (oldEp.bodyRule && !newEp.bodyRule) {
1073	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1074	  }
1075	
1076	  const violations: BodyViolation[] = [];
1077	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1078	  if (violations.length === 0) {
1079	    return { ...base, compatible: true, reasons: [] };
1080	  }
1081	  return {
1082	    ...base,
1083	    compatible: false,
1084	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1085	    example: {
1086	      ...base,
1087	      headers: { 'Content-Type': 'application/json' },
1088	      body: JSON.stringify(violations[0].value),
1089	    },
1090	  };
1091	}
