1601	function intersectObjects(flat: readonly RuleBranch[], where: string): Intersection {
1602	  const objs = flat.map((b) => b.rule as NormObject);
1603	  // 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）
1604	  const addl = objs.every((o) => o.addl);
1605	
1606	  const names: string[] = [];
1607	  const seen = new Set<string>();
1608	  for (const o of objs) {
1609	    for (const name of o.props.keys()) {
1610	      if (!seen.has(name)) {
1611	        seen.add(name);
1612	        names.push(name);
1613	      }
1614	    }
1615	  }
1616	
1617	  const props = new Map<string, NormRule>();
