1625	    }
1626	  };
1627	
1628	  for (const name of names) {
1629	    const isRequired = objs.some((o) => o.required.has(name));
1630	
1631	    // 真正约束该字段取值的声明分支（附精确来源位置）；以及首个禁止它出现的分支
1632	    // （未声明且该分支 additionalProperties 为 false）
1633	    const declarers: RuleBranch[] = [];
1634	    let forbiddener: RuleBranch | undefined;
1635	    for (let i = 0; i < flat.length; i += 1) {
1636	      const o = objs[i];
1637	      const sub = o.props.get(name);
1638	      if (sub !== undefined) {
1639	        declarers.push({ rule: sub, loc: `${flat[i].loc}.properties[${JSON.stringify(name)}]` });
