1668	    if (sub.tag === 'empty') {
1669	      if (isRequired) {
1670	        return {
1671	          tag: 'empty',
1672	          reason: `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${sub.reason}`,
1673	          loc: sub.loc,
1674	        };
1675	      }
1676	      if (!addl) {
1677	        // 可选字段交集为空、结果又拒绝额外字段：不声明即“禁止出现”，可表达
1678	        continue;
1679	      }
1680	      // 所有分支都允许额外字段时，无法表达“仅该字段禁止出现、其他字段任意”
1681	      noteInexpressible(
1682	        `可选字段 ${JSON.stringify(name)} 的各分支规则交集为空（${sub.reason}），` +
1683	          '且所有分支都允许额外字段，现有规则种类无法表达“仅禁止该字段出现”',
1684	        sub.loc,
