1848	        fields,
1849	        additionalProperties: rule.addl,
1850	      };
1851	      if (rule.nullable) {
1852	        out.nullable = true;
1853	      }
1854	      return out;
1855	    }
1856	    case 'array': {
1857	      const out: Record<string, unknown> = { type: 'array', items: normToRuleJson(rule.items) };
1858	      if (rule.nullable) {
1859	        out.nullable = true;
1860	      }
1861	      return out;
1862	    }
1863	    default: {
1864	      const out: Record<string, unknown> = { type: rule.kind };
1865	      if (rule.nullable) {
1866	        out.nullable = true;
1867	      }
1868	      return out;
1869	    }
