2286	function verifyRequests(
2287	  requests: readonly SnapshotRequest[],
2288	  specs: readonly EndpointSpec[],
2289	  requestsFile: string,
2290	  configFile: string,
2291	): VerifyReport {
2292	  const byKey = new Map<string, EndpointSpec>();
2293	  for (const spec of specs) {
2294	    byKey.set(`${spec.method} ${spec.path}`, spec);
2295	  }
2296	  const results = requests.map((req): VerifyResultEntry => {
2297	    const endpoint =
2298	      req.method === 'GET' || req.method === 'POST'
2299	        ? byKey.get(`${req.method} ${req.path}`)
2300	        : undefined;
2301	    if (!endpoint) {
2302	      return { id: req.id, outcome: 'unmatched', endpoint: null };
2303	    }
2304	    const key = `${endpoint.method} ${endpoint.path}`;
2305	    if (endpoint.bodyRule) {
2306	      const rejection = validateBodyWithContentType(req.contentType, req.body, endpoint.bodyRule);
2307	      if (rejection) {
2308	        return { id: req.id, outcome: 'rejected', endpoint: key, rejection };
2309	      }
2310	      return { id: req.id, outcome: 'passed', endpoint: key };
2311	    }
2312	    return { id: req.id, outcome: 'no_body_check', endpoint: key };
2313	  });
2314	  const accepted = results.filter(
2315	    (r) => r.outcome === 'passed' || r.outcome === 'no_body_check',
2316	  ).length;
2317	  return {
2318	    requestsFile,
2319	    configFile,
2320	    total: results.length,
2321	    accepted,
2322	    rejected: results.length - accepted,
2323	    results,
2324	  };
2325	}
