2638	// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
2639	function replayResponseJson(response: ReplayResponse): {
2640	  status: number;
2641	  body: { encoding: 'utf-8' | 'base64'; content: string };
2642	} {
2643	  return { status: response.status, body: encodeBodyLosslessly(response.body) };
2644	}
2645	
2646	type ReplayResultEntry =
2647	  | {
2648	      readonly id: number;
2649	      readonly outcome: 'same';
2650	      readonly response: ReturnType<typeof replayResponseJson>;
2651	    }
2652	  | {
2653	      readonly id: number;
2654	      readonly outcome: 'different';
2655	      // 差异点：状态码不同 / 正文原始字节不同（可同时为真）
2656	      readonly differences: { readonly status: boolean; readonly body: boolean };
2657	      readonly planned: ReturnType<typeof replayResponseJson>;
2658	      readonly response: ReturnType<typeof replayResponseJson>;
2659	    }
2660	  | { readonly id: number; readonly outcome: 'failed'; readonly reason: string };
2661	
2662	interface ReplayReport {
2663	  readonly requestsFile: string;
2664	  readonly port: number;
2665	  readonly timeoutMs: number;
2666	  readonly total: number;
2667	  readonly same: number;
2668	  readonly different: number;
2669	  readonly failed: number;
2670	  readonly results: readonly ReplayResultEntry[];
2671	}
2672	
2673	async function runReplay(requestsArg: string, port: number, timeoutMs: number): Promise<never> {
2674	  const requestsFile = path.resolve(requestsArg);
2675	
2676	  // 参数与全部记录有效后才连接：任何快照错误都不发任何请求
2677	  let requests: ReplayRequest[];
2678	  try {
2679	    requests = await loadReplaySnapshotFromFile(requestsFile);
2680	  } catch (e) {
2681	    process.stderr.write(`${APP_NAME}: replay 请求快照：${describeError(e)}\n`);
2682	    process.exit(2);
2683	  }
2684	
2685	  // 按输入顺序保留原编号逐条重放：前一条结束才发下一条
2686	  const results: ReplayResultEntry[] = [];
2687	  for (const request of requests) {
2688	    const exchange = await replayOne(port, request, timeoutMs);
2689	    if (!exchange.ok) {
2690	      results.push({ id: request.id, outcome: 'failed', reason: exchange.reason });
2691	      continue;
2692	    }
2693	    const { response } = exchange;
2694	    // 仅比较状态码与正文原始字节；计划正文按 UTF-8 编码
2695	    const statusDiff = response.status !== request.plannedStatus;
2696	    const bodyDiff = !response.body.equals(Buffer.from(request.plannedBody, 'utf8'));
2697	    if (!statusDiff && !bodyDiff) {
2698	      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
2699	    } else {
2700	      results.push({
2701	        id: request.id,
2702	        outcome: 'different',
2703	        differences: { status: statusDiff, body: bodyDiff },
2704	        planned: {
2705	          status: request.plannedStatus,
2706	          body: { encoding: 'utf-8', content: request.plannedBody },
2707	        },
2708	        response: replayResponseJson(response),
2709	      });
2710	    }
2711	  }
2712	
2713	  const same = results.filter((r) => r.outcome === 'same').length;
2714	  const different = results.filter((r) => r.outcome === 'different').length;
2715	  const failed = results.filter((r) => r.outcome === 'failed').length;
2716	  const report: ReplayReport = {
2717	    requestsFile,
2718	    port,
2719	    timeoutMs,
2720	    total: results.length,
2721	    same,
2722	    different,
2723	    failed,
2724	    results,
2725	  };
2726	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2727	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
2728	  process.exit(different === 0 && failed === 0 ? 0 : 1);
2729	}
