2831	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
2832	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
2833	function buildSceneHeaders(
2834	  item: ResponseSpec,
2835	  version: number,
2836	): { readonly [name: string]: string } {
2837	  const headers = versionHeaders(version);
2838	  let contentTypeSet = false;
2839	  for (const [name, value] of Object.entries(item.headers)) {
2840	    const lower = name.toLowerCase();
2841	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
2842	    if (lower === VERSION_HEADER.toLowerCase()) {
2843	      continue;
2844	    }
2845	    if (lower === 'content-type') {
2846	      contentTypeSet = true;
2847	    }
2848	    headers[name] = value;
2849	  }
2850	  // 文本正文的默认内容类型；配置显式给出时不覆盖
2851	  if (!contentTypeSet && item.body !== '') {
2852	    headers['Content-Type'] = 'text/plain; charset=utf-8';
2853	  }
2854	  return freezeHeaders(headers);
2855	}
