2894	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
2895	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
2896	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
2897	  let settled = false;
2898	  const settle = (status: DeliveryStatus): void => {
2899	    if (settled) {
2900	      return;
2901	    }
2902	    settled = true;
2903	    requestLog.markDelivered(recordId, status);
2904	  };
2905	  res.once('finish', () => settle('sent'));
2906	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
2907	  res.once('error', () => settle('interrupted'));
2908	}
