2924	type BodyOutcome = 'received' | 'aborted' | 'too-large';
2925	
2926	interface ReceivedBody {
2927	  readonly outcome: BodyOutcome;
2928	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
2929	  readonly body: Buffer;
2930	}
2931	
2932	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
2933	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
2934	  return new Promise((resolve) => {
2935	    let settled = false;
2936	    let size = 0;
2937	    const chunks: Buffer[] = [];
2938	    const finish = (outcome: BodyOutcome): void => {
2939	      if (!settled) {
2940	        settled = true;
2941	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
2942	      }
2943	    };
2944	    req.on('data', (chunk: Buffer) => {
2945	      size += chunk.byteLength;
2946	      if (size > MAX_BODY_BYTES) {
2947	        finish('too-large');
2948	        writeResponse(
2949	          res,
2950	          413,
2951	          versionHeaders(activeState.version, {
2952	            'Content-Type': 'text/plain; charset=utf-8',
2953	          }),
2954	          'payload too large\n',
2955	        );
2956	        // 等 413 刷出后再断开，避免客户端收不到响应
2957	        res.once('finish', () => req.socket.destroy());
2958	        return;
2959	      }
2960	      chunks.push(chunk);
2961	    });
2962	    req.on('end', () => finish('received'));
2963	    req.on('error', () => finish('aborted'));
2964	    req.on('aborted', () => finish('aborted'));
2965	    res.on('close', () => finish('aborted'));
2966	  });
2967	}
