3136	function shutdown(): void {
3137	  if (shuttingDown) {
3138	    return;
3139	  }
3140	  shuttingDown = true;
3141	  // 取消所有尚未发出的延迟响应
3142	  for (const timer of pendingTimers) {
3143	    clearTimeout(timer);
3144	  }
3145	  pendingTimers.clear();
3146	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
3147	  try {
3148	    server.closeAllConnections();
3149	  } catch {
3150	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
3151	  }
3152	  server.close(() => process.exit(0));
3153	  setTimeout(() => process.exit(0), 2000).unref();
3154	}
