198	// ---------------------------------------------------------------------------
199	// 独立参考实现：按 README 记录的规则语义判断“规则是否接受某 JSON 值”
200	// ---------------------------------------------------------------------------
201	
202	export interface RuleJson {
203	  readonly type: string;
204	  readonly nullable?: boolean;
205	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
206	  readonly additionalProperties?: boolean;
207	  readonly items?: RuleJson;
208	  readonly required?: boolean;
209	}
210	
211	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
212	  return typeof value === 'object' && value !== null && !Array.isArray(value);
213	}
214	
215	export function accepts(rule: RuleJson, value: unknown): boolean {
216	  // nullable:true 在原接受集合上加入 null；null 被接受时不产生子节点差异
217	  if (value === null && rule.nullable === true) {
218	    return true;
219	  }
220	  switch (rule.type) {
221	    case 'string':
222	      return typeof value === 'string';
223	    case 'boolean':
224	      return typeof value === 'boolean';
225	    case 'null':
226	      return value === null;
227	    case 'number':
228	      return typeof value === 'number' && Number.isFinite(value);
229	    case 'integer':
230	      return typeof value === 'number' && Number.isInteger(value);
231	    case 'array':
232	      return Array.isArray(value) && value.every((item) => accepts(rule.items as RuleJson, item));
233	    case 'object': {
234	      if (!isPlainJsonObject(value)) {
235	        return false;
236	      }
237	      const fields = rule.fields ?? {};
238	      for (const [name, fieldRule] of Object.entries(fields)) {
239	        const has = Object.prototype.hasOwnProperty.call(value, name);
240	        if (!has) {
241	          if (fieldRule.required === true) {
242	            return false;
243	          }
244	        } else if (!accepts(fieldRule, value[name])) {
245	          return false;
246	        }
247	      }
248	      if (rule.additionalProperties !== true) {
249	        for (const key of Object.keys(value)) {
250	          if (!Object.prototype.hasOwnProperty.call(fields, key)) {
251	            return false;
252	          }
253	        }
254	      }
255	      return true;
256	    }
257	    default:
258	      throw new Error(`参考实现遇到未知规则类型: ${JSON.stringify(rule.type)}`);
259	  }
260	}
261	
262	// ---------------------------------------------------------------------------
263	// 有限代表值域
264	// ---------------------------------------------------------------------------
265	//
266	// 设计目标：对本测试矩阵中的每一对（旧规则, 新规则），只要二者接受的 JSON
267	// 值集合不同，域中就存在一个见证值。为此域必须区分：
268	// - 整数与非整数（0/1 与 0.5）：区分 integer 与 number 的双向变化；
269	// - 字段缺失与 null（删除变体 与 显式 null）：区分“必填缺失”与“类型为 null”；
270	// - 空数组与非空数组（[] 与 [v]）：元素规则收紧在空数组上不可见；
271	// - 已声明字段与未声明额外字段（zz_extra）：区分 additionalProperties 两种策略；
272	// - 对象与数组的嵌套（递归到 MAX_DEPTH 层）。
273	//
274	// 构造方式（对每层对象规则）：
275	// - 标量代表值全集；
276	// - 空数组，以及元素代表值构成的单元素数组（若任一规则声明了数组元素规则，
277	//   元素域递归生成，否则用标量）；
278	// - 空对象、仅含额外字段的对象；
279	// - “基对象”：两规则声明字段的并集各取一个双方（退化为旧方）都接受的值，
280	//   再叠加额外字段；随后对每个字段做“删除”与“逐代表值替换”变体。
281	// 这样，新增必填字段由删除变体见证、字段类型收紧由替换变体见证、
282	// additionalProperties 收紧由叠加额外字段的对象见证、嵌套收紧由递归域见证。
283	//
284	// 注意：这只是针对本矩阵所测规则对的充分见证域，不构成对任意递归规则
285	// 包含关系的证明；矩阵中每条用例的期望都来自该域的穷举结果。
286	
287	const MAX_DEPTH = 2;
288	
289	// 标量代表值：覆盖 string（含空串）、整数、非整数、boolean、null
290	const SCALAR_REPS: readonly unknown[] = ['txt', '', 0, 1, 0.5, true, false, null];
291	
292	type FieldMap = { readonly [name: string]: RuleJson & { readonly required?: boolean } };
293	
294	function objectFields(rule: RuleJson | undefined): FieldMap {
295	  return rule !== undefined && rule.type === 'object' ? (rule.fields ?? {}) : {};
296	}
297	
298	function pickBase(
299	  subDomain: readonly unknown[],
300	  oldField: RuleJson | undefined,
301	  newField: RuleJson | undefined,
302	): unknown {
303	  const ok = (rule: RuleJson | undefined, v: unknown): boolean =>
304	    rule === undefined || accepts(rule, v);
305	  // 优先选双方规则都接受的值（基对象尽量是“好公民”），退化为旧规则接受，再退化为首元素
306	  return (
307	    subDomain.find((v) => ok(oldField, v) && ok(newField, v)) ??
308	    subDomain.find((v) => ok(oldField, v)) ??
309	    subDomain[0]
310	  );
311	}
312	
313	export function domainFor(
314	  oldRule: RuleJson | undefined,
315	  newRule: RuleJson | undefined,
316	  depth = 0,
317	): unknown[] {
318	  const values: unknown[] = [...SCALAR_REPS];
319	  if (depth >= MAX_DEPTH) {
320	    values.push([], {});
321	    return values;
322	  }
323	
324	  // 数组：空数组 + 元素代表值的单元素数组
325	  values.push([]);
326	  const itemOld = oldRule !== undefined && oldRule.type === 'array' ? oldRule.items : undefined;
327	  const itemNew = newRule !== undefined && newRule.type === 'array' ? newRule.items : undefined;
328	  const itemDomain =
329	    itemOld !== undefined || itemNew !== undefined
330	      ? domainFor(itemOld, itemNew, depth + 1)
331	      : SCALAR_REPS;
332	  for (const v of itemDomain) {
333	    values.push([v]);
334	  }
335	
336	  // 对象：空对象、额外字段对象、基对象及其删除/替换变体
337	  const fieldsOld = objectFields(oldRule);
338	  const fieldsNew = objectFields(newRule);
339	  const names = [...new Set([...Object.keys(fieldsOld), ...Object.keys(fieldsNew)])];
340	  let extra = 'zz_extra';
341	  while (names.includes(extra)) {
342	    extra = `${extra}_x`;
343	  }
344	  values.push({}, { [extra]: 0 }, { [extra]: 'txt' });
345	
346	  if (names.length > 0) {
347	    const subDomains = new Map<string, unknown[]>();
348	    const base: Record<string, unknown> = {};
349	    for (const name of names) {
350	      const sd = domainFor(fieldsOld[name], fieldsNew[name], depth + 1);
351	      subDomains.set(name, sd);
352	      base[name] = pickBase(sd, fieldsOld[name], fieldsNew[name]);
353	    }
354	    values.push(base, { ...base, [extra]: 0 }, { ...base, [extra]: 'txt' });
355	    for (const name of names) {
356	      const deleted = { ...base };
357	      delete deleted[name];
358	      values.push(deleted);
359	      for (const v of subDomains.get(name) as unknown[]) {
360	        if (!Object.is(v, base[name])) {
361	          values.push({ ...base, [name]: v });
362	        }
363	      }
364	    }
365	  }
366	
367	  return values;
368	}
