429	      { method: 'POST', path: '/c/widen', requestBody: { type: 'string' }, responses: [sceneResponse()] },
430	      // type:null -> 可空 string：null 仍接受，兼容
431	      { method: 'POST', path: '/c/null-ok', requestBody: { type: 'null' }, responses: [sceneResponse()] },
432	      // 移除根可空：不兼容（反例为根 null）
433	      { method: 'POST', path: '/c/narrow', requestBody: { type: 'string', nullable: true }, responses: [sceneResponse()] },
434	      // 移除嵌套字段可空：不兼容（反例含必要父对象与其他必填字段）
435	      {
436	        method: 'POST',
437	        path: '/c/nested',
438	        requestBody: {
439	          type: 'object',
440	          fields: {
441	            id: { type: 'integer', required: true },
442	            buyer: {
443	              type: 'object',
444	              required: true,
445	              fields: {
446	                name: { type: 'string', required: true },
