  const output = JSON.parse(result.stdout);
  assert.deepEqual(output.endpoints[0].requestBody, {
    type: 'object',
    nullable: true,
    fields: {
      a: { type: 'string', nullable: true, required: true },
      b: { type: 'array', items: { type: 'integer', nullable: true } },
    },
    additionalProperties: true,
  });

  // 导入结果可直接用于真实 serve
