function enumValuesOrError(enumRaw: readonly unknown[], kind: ScalarKind, nullable: boolean, where: string): { error: string } | { values: EnumValue[] } {
  if (enumRaw.length === 0) return { error: `${where} 必须是非空数组（至少一个候选值）` };
  const seen = new Set<unknown>();
  const values: EnumValue[] = [];
