```ts
// 枚举项是否满足节点类型（不做类型转换；数字按数值相等，0 与 -0 等价）
function enumItemConforms(kind: ScalarKind, item: unknown): boolean {
  switch (kind) {
    case 'string': return typeof item === 'string';
    case 'number': return typeof item === 'number' && Number.isFinite(item);
    case 'integer': return Number.isInteger(item);
    case 'boolean': return typeof item === 'boolean';
    case 'null': return item === null;
  }
}

// 校验并规范化枚举候选：非空、逐项符合节点类型与可空约定、按数值相等去重
// （顺序与重复值不影响语义）。返回错误消息或去重后的候选数组。
function enumValuesOrError(
  enumRaw: readonly unknown[],
  kind: ScalarKind,
  nullable: boolean,
  where: string,
): { error: string } | { values: EnumValue[] } {
  if (enumRaw.length === 0) {
    return { error: `${where} 必须是非空数组（至少一个候选值）` };
  }
  const seen = new Set<unknown>();
  const values: EnumValue[] = [];
  for (let i = 0; i < enumRaw.length; i += 1) {
    const item = enumRaw[i];
    const itemWhere = `${where}[${i}]`;
    if (item === null) {
      if (!nullable && kind !== 'null') {
        return { error: `${itemWhere} 为 null：接受 null 要求节点为 nullable:true 或 type:"null"` };
      }
    } else if (!enumItemConforms(kind, item)) {
      return { error: `${itemWhere} 必须是 ${kind}（与节点类型一致，不做类型转换），收到 ${JSON.stringify(item)}` };
    }
    if (!seen.has(item)) {
      seen.add(item);
      values.push(item as EnumValue);
    }
  }
  return { values };
}
```

